<?php
defined('BASEPATH') OR exit('No direct script access allowed');

/**
 * Rekap nilai otomatis untuk satu jadwal ujian.
 * Logika rekap (backupNilai, generateNilaiUjian, sortArrays) disalin apa adanya dari Cbtrekap.php
 * supaya hasilnya identik dengan tombol Rekap di menu Rekap Nilai.
 * Dipakai oleh Cbtjadwal saat menghapus jadwal.
 */
class Rekap_otomatis
{
    public $load;
    public $db;
    public $session;
    public $output;
    public $cbt;
    public $dashboard;
    public $master;
    public $dropdown;
    public $alasan = '';
    // true = jika tidak ada satu pun siswa yang nilainya sudah final (selesai & dikoreksi), anggap tidak ada yang perlu direkap
    public $lewati_tanpa_nilai_final = false;
    public $err_rekap = null;
    public $err_nilai = null;

    public function __construct()
    {
        $CI =& get_instance();
        $CI->load->model("Cbt_model", "cbt");
        $CI->load->model("Dashboard_model", "dashboard");
        $CI->load->model("Master_model", "master");
        $CI->load->model("Dropdown_model", "dropdown");

        $this->load = $CI->load;
        $this->db = $CI->db;
        $this->session = $CI->session;
        $this->output = $CI->output;
        $this->cbt = $CI->cbt;
        $this->dashboard = $CI->dashboard;
        $this->master = $CI->master;
        $this->dropdown = $CI->dropdown;
    }

    // dipanggil oleh backupNilai() di bawah; di sini tidak mengirim output apa pun
    public function output_json($data, $encode = true)
    {
        return;
    }

    /**
     * Pastikan jadwal sudah terekap.
     * @return bool true jika aman dihapus (sudah/berhasil direkap, atau belum pernah dikerjakan siswa)
     */
    public function pastikan($id_jadwal)
    {
        $jadwal = $this->db->get_where("cbt_jadwal", ["id_jadwal" => $id_jadwal])->row();
        if (!$jadwal || $jadwal->rekap == 1) {
            return true;
        }

        $dikerjakan = $this->cbt->getJadwalTerpakai($id_jadwal);
        if (!isset($dikerjakan[$id_jadwal]) || count($dikerjakan[$id_jadwal]) == 0) {
            return true;
        }

        if ($this->lewati_tanpa_nilai_final) {
            $final = $this->db->where("id_jadwal", $id_jadwal)->where("dikoreksi", "1")->count_all_results("cbt_nilai");
            if ($final == 0) {
                return true;
            }
        }

        $this->alasan = '';
        $this->err_rekap = null;
        $this->err_nilai = null;
        ob_start();
        $this->backupNilai($id_jadwal);
        $keluaran = trim(strip_tags(ob_get_clean()));
        $flash = trim(strip_tags((string) $this->session->flashdata("rekapnilai")));
        $this->session->unset_userdata("rekapnilai");

        $jadwal = $this->db->get_where("cbt_jadwal", ["id_jadwal" => $id_jadwal])->row();
        $ok = $jadwal && $jadwal->rekap == 1;

        if (!$ok) {
            $bagian = [];
            if (!empty($this->err_rekap["message"])) { $bagian[] = "DB cbt_rekap: " . $this->err_rekap["message"]; }
            if (!empty($this->err_nilai["message"])) { $bagian[] = "DB cbt_rekap_nilai: " . $this->err_nilai["message"]; }
            if ($flash !== '') { $bagian[] = $flash; }
            if ($keluaran !== '') { $bagian[] = "PHP: " . substr(preg_replace('/\s+/', ' ', $keluaran), 0, 300); }
            $bagian[] = $this->diagnosa($id_jadwal, array_keys($dikerjakan[$id_jadwal]));
            $this->alasan = implode(" | ", array_filter($bagian));
        }
        return $ok;
    }

    // Cari tahu kenapa nilai tidak bisa dihitung: siswa yang mengerjakan harus ada di daftar peserta
    private function diagnosa($id_jadwal, $id_siswa_mengerjakan)
    {
        $info = $this->cbt->getJadwalById($id_jadwal);
        if (!$info) {
            return "DIAGNOSA: data jadwal tidak ditemukan";
        }
        $kelas = [];
        $bank_kelas = @unserialize($info->bank_kelas ?? '');
        if (is_array($bank_kelas)) {
            foreach ($bank_kelas as $v) {
                if (!empty($v["kelas_id"])) { $kelas[] = $v["kelas_id"]; }
            }
        }
        if (count($kelas) == 0) {
            return "DIAGNOSA: bank soal jadwal ini belum punya kelas";
        }
        $peserta = $this->cbt->getSiswaByKelas($info->id_tp, $info->id_smt, $kelas);
        $id_peserta = [];
        foreach ($peserta as $p) { $id_peserta[] = $p->id_siswa; }
        $hilang = array_diff($id_siswa_mengerjakan, $id_peserta);

        if (count($peserta) == 0) {
            return "DIAGNOSA: tidak ada siswa di kelas jadwal ini yang punya ruang/sesi, nomor peserta, dan status aktif di buku induk";
        }
        if (count($hilang) > 0) {
            return "DIAGNOSA: " . count($hilang) . " siswa yang mengerjakan (id_siswa " . implode(",", $hilang) . ") tidak masuk daftar peserta kelas ini (cek Atur Ruang/Sesi, Nomor Peserta, buku induk, atau kelasnya sudah dipindah)";
        }
        $final = $this->db->where("id_jadwal", $id_jadwal)->where("dikoreksi", "1")->count_all_results("cbt_nilai");
        if ($final == 0) {
            return "DIAGNOSA: " . count($id_siswa_mengerjakan) . " siswa mengerjakan tetapi belum ada yang berstatus selesai/dikoreksi, jadi tidak ada nilai untuk direkap";
        }
        return "DIAGNOSA: siswa terdaftar semua; kemungkinan gagal menyimpan ke tabel rekap (lihat pesan DB)";
    }

